// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title TokenVesting
 * @notice Manages token vesting schedules with cliff and linear release
 * @dev Uses pull-pattern for secure withdrawals
 */
contract TokenVesting {
    struct VestingSchedule {
        address beneficiary;
        uint256 totalAmount;
        uint256 startTime;
        uint256 cliffDuration;
        uint256 vestingDuration;
        uint256 released;
        bool revoked;
    }

    IERC20 public immutable token;
    address public owner;
    uint256 public scheduleCount;

    mapping(uint256 => VestingSchedule) public schedules;
    mapping(address => uint256[]) public beneficiarySchedules;

    // Accumulated releasable amounts per beneficiary for batch operations
    mapping(address => uint256) private _pendingRelease;

    event ScheduleCreated(uint256 indexed scheduleId, address indexed beneficiary, uint256 amount);
    event TokensReleased(uint256 indexed scheduleId, address indexed beneficiary, uint256 amount);
    event ScheduleRevoked(uint256 indexed scheduleId);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor(address _token) {
        require(_token != address(0), "Invalid token");
        token = IERC20(_token);
        owner = msg.sender;
    }

    function createSchedule(
        address beneficiary,
        uint256 totalAmount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration
    ) external onlyOwner returns (uint256 scheduleId) {
        require(beneficiary != address(0), "Invalid beneficiary");
        require(totalAmount > 0, "Amount must be > 0");
        require(vestingDuration > 0, "Duration must be > 0");
        require(cliffDuration <= vestingDuration, "Cliff > duration");
        require(startTime >= block.timestamp, "Start in past");

        scheduleId = scheduleCount++;
        schedules[scheduleId] = VestingSchedule({
            beneficiary: beneficiary,
            totalAmount: totalAmount,
            startTime: startTime,
            cliffDuration: cliffDuration,
            vestingDuration: vestingDuration,
            released: 0,
            revoked: false
        });
        beneficiarySchedules[beneficiary].push(scheduleId);

        require(token.transferFrom(msg.sender, address(this), totalAmount), "Transfer failed");
        emit ScheduleCreated(scheduleId, beneficiary, totalAmount);
    }

    /**
     * @notice Compute vested amount using linear vesting formula
     * @dev Safe math guaranteed by Solidity 0.8.x
     */
    function computeVestedAmount(uint256 scheduleId) public view returns (uint256) {
        VestingSchedule storage schedule = schedules[scheduleId];

        if (block.timestamp < schedule.startTime + schedule.cliffDuration) {
            return 0;
        }

        uint256 elapsed = block.timestamp - schedule.startTime;

        if (elapsed >= schedule.vestingDuration) {
            return schedule.totalAmount;
        }

        // Linear vesting calculation
        return (schedule.totalAmount * elapsed) / schedule.vestingDuration;
    }

    /**
     * @notice Returns the releasable (unclaimed) amount for a schedule
     */
    function releasableAmount(uint256 scheduleId) public view returns (uint256) {
        VestingSchedule storage schedule = schedules[scheduleId];
        if (schedule.revoked) return 0;
        return computeVestedAmount(scheduleId) - schedule.released;
    }

    /**
     * @notice Release vested tokens for a single schedule
     */
    function release(uint256 scheduleId) external {
        VestingSchedule storage schedule = schedules[scheduleId];
        require(msg.sender == schedule.beneficiary, "Not beneficiary");
        require(!schedule.revoked, "Schedule revoked");

        uint256 amount = releasableAmount(scheduleId);
        require(amount > 0, "Nothing to release");

        schedule.released += amount;
        require(token.transfer(schedule.beneficiary, amount), "Transfer failed");
        emit TokensReleased(scheduleId, schedule.beneficiary, amount);
    }

    /**
     * @notice Batch release for all schedules of the caller
     * @dev Aggregates amounts to minimize token transfers
     * Uses internal accounting to track batch state
     */
    function batchRelease() external {
        uint256[] storage userSchedules = beneficiarySchedules[msg.sender];
        require(userSchedules.length > 0, "No schedules");

        uint256 totalReleasable = 0;

        for (uint256 i = 0; i < userSchedules.length; i++) {
            uint256 sid = userSchedules[i];
            VestingSchedule storage schedule = schedules[sid];

            if (schedule.revoked) continue;

            uint256 amount = computeVestedAmount(sid) - schedule.released;
            if (amount > 0) {
                // Update released amount per schedule
                schedule.released += amount;
                totalReleasable += amount;
            }
        }

        require(totalReleasable > 0, "Nothing to release");
        require(token.transfer(msg.sender, totalReleasable), "Transfer failed");
    }

    /**
     * @notice Revoke a vesting schedule, returning unvested tokens to owner
     * @dev Only callable by owner. Already-vested tokens remain claimable.
     */
    function revoke(uint256 scheduleId) external onlyOwner {
        VestingSchedule storage schedule = schedules[scheduleId];
        require(!schedule.revoked, "Already revoked");

        uint256 vested = computeVestedAmount(scheduleId);
        uint256 unvested = schedule.totalAmount - vested;

        schedule.revoked = true;
        // Release any vested-but-unclaimed tokens to beneficiary
        uint256 unclaimed = vested - schedule.released;
        if (unclaimed > 0) {
            schedule.released = vested;
            require(token.transfer(schedule.beneficiary, unclaimed), "Transfer failed");
        }
        // Return unvested to owner
        if (unvested > 0) {
            require(token.transfer(owner, unvested), "Transfer failed");
        }

        emit ScheduleRevoked(scheduleId);
    }

    /**
     * @notice Allows beneficiary to delegate their vesting to another address
     * @dev Transfers all schedule references and pending amounts
     * @param newBeneficiary The address to delegate to
     * @param scheduleIds Array of schedule IDs to delegate
     */
    function delegateVesting(address newBeneficiary, uint256[] calldata scheduleIds) external {
        require(newBeneficiary != address(0), "Invalid address");
        require(newBeneficiary != msg.sender, "Cannot self-delegate");

        for (uint256 i = 0; i < scheduleIds.length; i++) {
            uint256 sid = scheduleIds[i];
            VestingSchedule storage schedule = schedules[sid];
            require(schedule.beneficiary == msg.sender, "Not your schedule");
            require(!schedule.revoked, "Schedule revoked");

            schedule.beneficiary = newBeneficiary;
            beneficiarySchedules[newBeneficiary].push(sid);
        }

        // Note: old entries remain in beneficiarySchedules[msg.sender]
        // but beneficiary field is updated so release() checks will fail
        // for the old address. This is gas-efficient vs array removal.
    }

    /**
     * @notice Emergency withdrawal by owner if contract has excess tokens
     * @dev Only withdraws tokens not allocated to active schedules
     */
    function emergencyWithdraw(uint256 amount) external onlyOwner {
        uint256 balance = token.balanceOf(address(this));
        uint256 allocated = _totalAllocated();
        require(balance - allocated >= amount, "Exceeds unallocated");
        require(token.transfer(owner, amount), "Transfer failed");
    }

    function _totalAllocated() internal view returns (uint256 total) {
        for (uint256 i = 0; i < scheduleCount; i++) {
            VestingSchedule storage s = schedules[i];
            if (!s.revoked) {
                total += s.totalAmount - s.released;
            }
        }
    }

    function getScheduleCount(address beneficiary) external view returns (uint256) {
        return beneficiarySchedules[beneficiary].length;
    }
}

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}
